import _codecs
for policy in ('ignore', 'replace', 'xmlcharrefreplace', 'backslashreplace', 'namereplace', 'surrogateescape', 'surrogatepass'):
    handler = _codecs.lookup_error(policy)
    for mode in ('encode', 'decode', 'translate'):
        for text in ('', 'a', '\ud800', '\udc80', 'a\udc80\ud800'):
            for start in (-5, -1, 0, 1, 2, 5):
                for end in (-5, -1, 0, 1, 2, 5):
                    if mode == 'encode':
                        error = UnicodeEncodeError('utf-8', text, start, end, 'reason')
                    elif mode == 'decode':
                        error = UnicodeDecodeError('utf-8', text.encode('utf-8', 'surrogatepass'), start, end, 'reason')
                    else:
                        error = UnicodeTranslateError(text, start, end, 'reason')
                    try:
                        result = handler(error)
                    except BaseException as caught:
                        result = (type(caught).__name__, caught.args, caught is error)
                    print(repr((policy, mode, text, start, end, result)))
